import os
from itertools import cycle, islice
from pprint import pformat
from typing import Optional, List

from taf.rfrl.utilities.robot.RobotWrapper import RobotWrapper

from taf.rfrl.csv4all.resources.node.feature.netact.exceptions import PreconditionBeforeFallack, ExecutingResetLoopFail, \
    NodeVerificationFail
from taf.rfrl.csv4all.resources.node.feature.netact.netact import Netact
from taf.rfrl.csv4all.resources.node.feature.netact.netact_node_factory import NetactNodeFactory
from taf.rfrl.csv4all.resources.test_cases import NetactFeatureTest, ParallelUpgradeRollbackTest, UpgradeTest
from taf.rfrl.csv4all.resources.test_cases.exceptions import IterationFailedError, IntegrationFailedError
from taf.rfrl.csv4all.resources.node.feature.netact.netact_node import NetactNode
from taf.rfrl.csv4all.resources.utilities.decorators import function_wrapper, method_decorator
from taf.rfrl.csv4all.resources.utilities.utilities import test_logger


class ParallelNetactTest(ParallelUpgradeRollbackTest):
    def __init__(self, nodes_details, test_nodes_details: List[dict], iterations_per_node: int,
                 netact_dict: dict, report: bool, calculate_kpi: Optional[bool] = True,
                 kpi_targets: Optional[dict] = None,
                 use_dcap: Optional[bool] = False, qc_domain: Optional[str] = None, qc_id: Optional[str] = None,
                 qc_project: Optional[str] = None, customers_list: Optional[list] = None,
                 report_comment: Optional[str] = None, sw_build: Optional[str] = None, topology: Optional[str] = None,
                 use_external_storage: Optional[bool] = False, download_path: Optional[str] = None,
                 use_testpackage: Optional[bool] = False, restore_to_target_sw: Optional[bool] = False,
                 feature: Optional[str] = None, rollback: Optional[bool] = True, fallback: Optional[bool] = False,
                 stop_test_after_fail: bool = False, deintegrate_after_test: bool = True,
                 integrate_before_test: bool = True, config_type: str = None,
                 artifactory_location: str = "espoo2", package_suffix: str = "A54",
                 l3_call_method: Optional[callable] = None, synchronize_software_on_passive: bool = False,
                 yaft_path: str = "/home/ute", virtualenv_dir: str = None, detailed_console_log: bool = True,
                 collect_passed_logs: int = 0, cm_provision: bool = True, diagnostic_check: bool = False):
        super().__init__(nodes_details, test_nodes_details, iterations_per_node, report,
                         calculate_kpi, kpi_targets, use_dcap, qc_domain, qc_id, qc_project, customers_list,
                         report_comment, sw_build, topology, use_external_storage, download_path, restore_to_target_sw,
                         use_testpackage, stop_test_after_fail, artifactory_location, package_suffix, l3_call_method,
                         synchronize_software_on_passive, yaft_path, virtualenv_dir, detailed_console_log,
                         collect_passed_logs=collect_passed_logs, diagnostic_check=diagnostic_check)
        self.feature = feature
        self.netact_dict = netact_dict
        self.config_type = config_type
        self.node_factory = NetactNodeFactory()
        self.nescrotta = None
        self.perform_rollback = rollback
        self.perform_fallback = fallback
        self.deintegrate_after_test = deintegrate_after_test
        self.integrate_before_test = integrate_before_test
        self.check_cm_provision = cm_provision
        if self.report_to_rp:
            self.test_reporter.tool = "MantaRay"
        self.netact_feature = NetactFeatureTest(nodes_details=nodes_details,
                                                test_nodes_details=test_nodes_details,
                                                iterations_per_node=iterations_per_node,
                                                report=report,
                                                customers_list=customers_list,
                                                netact_dict=netact_dict, feature=feature,
                                                config_type=config_type,
                                                use_testpackage=use_testpackage,
                                                package_suffix=package_suffix,
                                                download_path=download_path,
                                                use_external_storage=use_external_storage)

    def test_setup(self):
        self.setup_for_netact_test()
        self.netact_feature.setup_nescrotta()
        self.prepare_uboot_scripts()
        self.setup_netact_and_integrate_nodes()
        self.prepare_sw_packages()
        self.netact_feature.current_logs_dir = os.path.join(self.log_dir, self.current_iteration)

    def setup_for_netact_test(self):
        super(UpgradeTest, self).test_setup()
        self.netact_feature.wft = self.wft
        self.netact_feature.node_master = self.test_nodes[0]
        self.netact_feature.test_nodes = self.test_nodes
        self._log_if_reports_to_uuf_wont_be_sent()
        self.check_source_and_target_sw()
        self.prepare_uboot_scripts()
        self.yaft_checkout()
        self.check_validation_scf_before_test()
        self.hwf_migration_precheck()
        self.check_oran_files_exists()

    def test(self):
        self.run_iteration_precondition()
        self._set_current_logs_dir(None)
        self.failed_nodes = self.parallel_test_operation()
        self.report_results_to_uuf_dashboard()
        self.run_parallel_iteration_postcondition()
        if self.perform_fallback:
            if self.perform_rollback:
                self.perform_precondition_before_fallback()
                self.software_update_test("update_before_fallback")
            self.software_fallback_test()
        if self.failed_nodes:
            raise IterationFailedError(f"Iteration Failed. Issues detected on nodes : {self.failed_nodes}")
        else:
            test_logger(f"Iteration No. {self.current_iteration.split('_')[1]} Passed", hyperlink=True)
        if self.l3_call_method and not self.l3_call_result:
            raise IterationFailedError("Iteration Failed. L3 Call failed.")

    def test_teardown(self):
        self.current_logs_dir = f"{self.log_dir}/Test_Teardown"
        try:
            super().test_teardown()
        finally:
            if self.deintegrate_after_test:
                for node in self.test_nodes:
                    node: NetactNode
                    try:
                        node.deintegrate_mrbts()
                    except Exception as e:
                        test_logger(e, "ERROR")
            self.teardown_netact()
            self.netact_feature.umount_nescrotta()

    def setup_netact_and_integrate_nodes(self):
        for node in self.test_nodes:
            node: NetactNode
            node.netact = Netact(**self.netact_dict)
            node.mplane = node.set_node_mplane()
        self.setup_netact()
        if self.integrate_before_test:
            self.integrate_all_nodes()

    @function_wrapper
    def setup_netact(self):
        for node in self.test_nodes:
            node: NetactNode
            node.netact.setup_netact()
            self.log_netact_information(node)

    @function_wrapper
    def log_netact_information(self, node):
        netact_vars = vars(node.netact).copy()
        netact_vars["ssh_password"] = ""
        test_logger(pformat(netact_vars), console=False)

    @function_wrapper
    def integrate_all_nodes(self):
        integrate_results = self.multi_runner.run_operations_in_sequence(self.test_nodes,
                                                                         NetactNode.integrate_parallel_mrbts)
        if integrate_results.get("Failed"):
            failed_nodes = {node for node in {*integrate_results['Failed'].keys()}}
            test_logger(f"Integration Failed for Nodes: {failed_nodes}")
            raise IntegrationFailedError()

    @method_decorator()
    def prepare_sw_packages(self):
        sw_lists_to_import = {self.netact_feature.node_master.target_sw}
        for node in self.test_nodes:
            if node._check_if_paths_are_similar():
                self.download_builds_from_wft(node.target_sw)
                self.set_target_sw_path(node)
                continue
            if self.use_testpackage:
                target_sw_names = [node.target_sw, f"{node.target_sw}T1", f"{node.target_sw}T2"]
                target_sw_list = list(islice(cycle(target_sw_names), self.iterations_per_node + 1))
                node.iter_target_sw_list = iter(target_sw_list)
        if self.perform_fallback:
            for node in self.test_nodes:
                sw_lists_to_import.add(node.source_sw)

        self.netact_feature.import_sw_to_netact(sw_lists_to_import)

    def software_update_test(self, operation: str = "update"):
        with RobotWrapper("Software Update Test", "kw"):
            self._set_netact_target_sw()
            self.failed_nodes = self.parallel_update_sw_operation(operation)
            self.check_parallel_provision_from_target_sw()
            self.failed_nodes.update(self.check_connection_to_netact(self.check_cm_provision))
            self.verify_parallel_cells_from_netact()
            if self.current_iteration == "Iteration_1":
                self.failed_nodes.update(self.validate_all_nodes_scf())
            self.failed_nodes.update(self.perform_dnr_partition_check_on_all_nodes(check_after_upgrade=True))
            self._log_operation_status(operation, self.failed_nodes)

    @function_wrapper
    def teardown_netact(self):
        for node in self.test_nodes:
            node: NetactNode
            node.netact.teardown_netact()

    def parallel_test_operation(self):
        self.set_timestamp_reporting_and_kpi()
        if not self.perform_rollback and self.perform_fallback:
            self.perform_precondition_before_fallback()
        self.software_update_test()
        if self.perform_rollback:
            self.software_rollback_test()
        return self.failed_nodes

    def software_fallback_test(self):
        with RobotWrapper("Software Fallback Test", "kw"):
            test_logger("Fallback Test started")
            operation = "fallback"
            for node in self.test_nodes:
                node.logsverify.reset_check = False
            try:
                self.multi_runner.start_log_tracing_all_nodes()
                self.execute_reset_loop_on_test_nodes()
                for node in self.test_nodes:
                    node.reset_admin()
                self.verify_active_sw_on_test_nodes_after_fallback()
                self.verify_test_nodes_after_fallback()
                self.check_connection_on_test_nodes_after_fallback_and_collect_snapshot()
                test_logger(f"{operation.upper()} PASSED", hyperlink=True)
                return set()
            except Exception as e:
                test_logger(f"{operation.upper()} FAILED", "error")
                try:
                    self.gather_mumin_logs_and_snapshot(operation)
                except Exception as e:
                    test_logger(e, console=False)
                return self.failed_nodes
            finally:
                self.postcondition_after_fallback()

    def precondition_before_fallback(self):
        with RobotWrapper("Precondition Before Fallback", "kw"):
            self.perform_precondition_before_fallback()

    @method_decorator()
    def perform_precondition_before_fallback(self):
        precondition_results = self.multi_runner.run_operations_as_threads_and_return(
            self.test_nodes,
            NetactNode.precondition_before_fallback
        )
        if precondition_results.get("Failed"):
            failed_nodes = {node_alias for node_alias in precondition_results["Failed"].keys()}
            test_logger(f"Multi node Precondition failed on: {','.join(failed_nodes)}", "ERROR")
            raise PreconditionBeforeFallack()
        return True

    @method_decorator()
    def execute_reset_loop_on_test_nodes(self):
        reset_loop_results = self.multi_runner.run_operations_as_threads_and_return(
            self.test_nodes,
            NetactNode.execute_reset_loop
        )
        if reset_loop_results.get("Failed"):
            failed_nodes = {node_alias for node_alias in reset_loop_results["Failed"].keys()}
            test_logger(f"Multi node Reset Loop failed on: {','.join(failed_nodes)}", "ERROR")
            raise ExecutingResetLoopFail()
        return True

    @method_decorator()
    def verify_active_sw_on_test_nodes_after_fallback(self):
        for node in self.test_nodes:
            node.verify_active_sw_after_fallback()

    @method_decorator()
    def verify_test_nodes_after_fallback(self):
        node_verification = self.multi_runner.run_operations_as_threads_and_return(
            self.test_nodes,
            NetactNode.verify_node_after_fallback
        )
        if node_verification.get("Failed"):
            failed_nodes = {node_alias for node_alias in node_verification["Failed"].keys()}
            test_logger(f"Multi node Verification failed on: {','.join(failed_nodes)}", "ERROR")
            raise NodeVerificationFail()
        return True

    @method_decorator()
    def check_connection_on_test_nodes_after_fallback_and_collect_snapshot(self):
        operation = "fallback"
        if self.check_connection_to_netact():
            raise
        if not self.passed_logs_gathered:
            self.gather_mumin_logs_and_snapshot(operation)
            for node in self.test_nodes:
                self.netact_feature.send_snapshot_to_nescrotta(node, operation)

    @method_decorator()
    def check_connection_to_netact(self, cm_provision: bool = False):
        connection_verification = self.multi_runner.run_operations_as_threads_and_return(
            self.test_nodes,
            NetactNode.check_connection_to_netact
        )
        if cm_provision:
            connection_verification.update(self.multi_runner.run_operations_in_sequence(
                self.test_nodes,
                NetactNode.perform_cm_provision
            ))
        if connection_verification.get("Failed"):
            failed_nodes = {node_alias for node_alias in connection_verification["Failed"].keys()}
            test_logger(f"Multi node Verification failed on: {','.join(failed_nodes)}", "ERROR")
            return failed_nodes
        self.check_cm_provision = False
        return set()

    @function_wrapper
    def postcondition_after_fallback(self):
        for node in self.test_nodes:
            node.logsverify.reset_check = True
        fallback_clear = self.multi_runner.run_operations_as_threads_and_return(
            self.test_nodes,
            NetactNode.postcondition_after_fallback
        )
        if fallback_clear.get("Failed"):
            failed_nodes = {node_alias for node_alias in fallback_clear["Failed"].keys()}
            test_logger(f"Multi node clearing fallback fault failed on: {','.join(failed_nodes)}", "ERROR")
            raise Exception(f"Multi node clearing fallback fault failed on: {','.join(failed_nodes)}")
        return True

    @method_decorator()
    def check_parallel_provision_from_target_sw(self):
        self.netact_feature.current_logs_dir = os.path.join(self.log_dir, self.current_iteration)
        try:
            test_logger(f"Checking provision from same software")
            provision_sw = self.multi_runner.run_operations_as_threads_and_return(
                self.test_nodes,
                NetactNode.update_sw
            )
            if provision_sw.get("Failed"):
                failed_nodes = {node_alias for node_alias in provision_sw["Failed"].keys()}
                test_logger(f"Multi node provision from same software failed on: {','.join(failed_nodes)}",
                            "ERROR")
                raise
            test_logger(f"PROVISION CHECK FROM SAME SOFTWARE PASSED", hyperlink=True)
        except Exception as e:
            test_logger(f"PROVISION CHECK FROM SAME SOFTWARE FAILED", log_level="ERROR")
            test_logger(e, "error")
            if not self.use_dcap:
                try:
                    self.gather_mumin_logs_and_snapshot("self_provision")
                except Exception as e:
                    test_logger(e, console=False)

    @method_decorator()
    def verify_parallel_cells_from_netact(self):
        self.netact_feature.current_logs_dir = os.path.join(self.log_dir, self.current_iteration)
        cells_verification = self.multi_runner.run_operations_as_threads_and_return(
            self.test_nodes,
            NetactNode.verify_cells_from_netact
        )
        if cells_verification.get("Failed"):
            failed_nodes = {node_alias for node_alias in cells_verification["Failed"].keys()}
            test_logger(f"Multi node cells verification failed on: {','.join(failed_nodes)}", "ERROR")
            return failed_nodes
        return set()

    def run_parallel_iteration_postcondition(self):
        with RobotWrapper("Iteration Postcondition", "kw"):
            sw_to_check = "source_sw" if self.perform_rollback else "target_sw"
            self.verify_active_sw_on_test_nodes(sw_to_check, rollback_on_fail=True)

    def _set_netact_target_sw(self):
        for node in self.test_nodes:
            if self.use_testpackage:
                node.netact_target_sw = next(node.iter_target_sw_list)
            else:
                node.netact_target_sw = self.netact_feature.get_target_sw(node.target_sw)
